    <description>Renders a single question card for a coaching step, including questions, DEEP processes, and tips. Handles navigation buttons based on the step.</description>
    <content><![CDATA[import React , { useCallback } from 'react';
import { StepData, QuestionData } from '../types';
import DeepProcess from './DeepProcess';
import TipBox from './TipBox';

interface QuestionCardProps {
  stepData: StepData;
  onPrevStep: (stepId: number) => void;
  onNextStep: (stepId: number) => void;
  onComplete: () => void;
  isActive: boolean;
}

const QuestionCard: React.FC<QuestionCardProps> = ({
  stepData,
  onPrevStep,
  onNextStep,
  onComplete,
  isActive,
}) => {
  const isLastStep = stepData.id === 4;
  const isFirstStep = stepData.id === 1;

  const handlePrev = useCallback(() => {
    onPrevStep(stepData.id - 1);
  }, [onPrevStep, stepData.id]);

  const handleNext = useCallback(() => {
    onNextStep(stepData.id + 1);
  }, [onNextStep, stepData.id]);

  const handleComplete = useCallback(() => {
    onComplete();
  }, [onComplete]);

  return (
    <div className={`question-card p-6 rounded-xl mb-5 border-l-4 border-indigo-500  ${isActive ? 'opacity-100' : 'opacity-0' } transition-opacity duration-500`}>
      <h3 className="text-xl font-bold mb-4 text-gray-800">{stepData.title}</h3>
      {stepData.questions.map((question, index) => (
        <div key={index} className="mb-8">
          <p className="text-lg text-gray-700 mb-2">{question.title}</p>
          <p className="text-gray-700 mb-4">{question.text}</p>
          <DeepProcess steps={question.deepProcess} />
          <TipBox tip={question.tip} />
        </div>
      ))}

      <div className="flex justify-between mt-4">
        {!isFirstStep && (
          <button
            onClick={handlePrev}
            className="prev-step-btn px-8 py-4 border-2 border-indigo-500 rounded-lg cursor-pointer font-bold text-base transition-all duration-300 bg-white text-indigo-500 hover:bg-gray-50"
          >
            이전
          </button>
        )}
        {isLastStep ? (
          <button
            onClick={handleComplete}
            className="complete-btn px-8 py-4 border-none rounded-lg cursor-pointer font-bold text-base transition-all duration-300 bg-gradient-to-br from-green-500 to-green-700 text-white hover:transform hover:-translate-y-0.5 hover:shadow-lg hover:shadow-green-500/40"
          >
            완료
          </button>
        ) : (
          <button
            onClick={handleNext}
            className="next-step-btn px-8 py-4 border-none rounded-lg cursor-pointer font-bold text-base transition-all duration-300 bg-gradient-to-br from-indigo-500 to-purple-700 text-white hover:transform hover:-translate-y-0.5 hover:shadow-lg hover:shadow-indigo-500/40"
          >
            다음
          </button>
        )}
      </div>
    </div>
  );
};

export default QuestionCard;]]></content>
